<body><?php include 'sidebar.php'; ?><main class="shell"><header class="topbar"><a class="brand" href="user-panel.php"><img src="assets/logo.png" alt="Smart Farming logo"> Smart Farming</a><a class="back" href="user-panel.php">← ડેશબોર્ડ પર પાછા</a></header><section class="hero"><div class="hero-copy"><p class="eyebrow">Smart Farming · પાક સુરક્ષા</p><h1>પાકને નુકસાન કરતા જીવાતને સમયસર ઓળખો.</h1><p>પાંદડા, ડાળી અને ફળની નિયમિત તપાસથી નુકસાન ઘટે છે. પાક પસંદ કરો, લક્ષણ મેળવો અને સૌપ્રથમ સુરક્ષિત IPM પગલાં જાણો.</p></div><div class="hero-badge">✓ પહેલા ઓળખ · પછી યોગ્ય પગલું</div></section><section class="quick"><article class="quick-card"><div class="quick-icon">🔎</div><div><strong>દર 3–4 દિવસે તપાસો</strong><span>પાંદડાની નીચે, નવી કૂંપળ અને ફળ જુઓ.</span></div></article><article class="quick-card"><div class="quick-icon">🪤</div><div><strong>ટ્રેપથી નજર રાખો</strong><span>સ્ટિકી અને ફેરોમોન ટ્રેપ સમયસર બદલો.</span></div></article><article class="quick-card"><div class="quick-icon">🌿</div><div><strong>IPM ને પ્રાથમિકતા</strong><span>સ્વચ્છતા, કુદરતી શત્રુ અને પાક ફેરબદલી.</span></div></article></section><div class="section-head"><div><h2>જીવાત અને રોગ માર્ગદર્શન</h2><p>તમારા પાકનું નામ અથવા જીવાત શોધો. કાર્ડ પસંદ કરતાં પગલાં ખુલશે.</p></div><span id="count" class="count"></span></div><div class="filters"><input id="search" type="search" placeholder="પાક અથવા જીવાત શોધો..."><select id="cropFilter"><option value="all">બધા પાક</option></select></div><section id="grid" class="pest-grid" aria-live="polite"></section><section id="detail" class="detail" aria-live="polite"><div id="detailVisual" class="detail-visual"><div id="detailIcon" class="big-icon">🐛</div><p id="detailCrop"></p><h2 id="detailName"></h2></div><div class="detail-content"><button id="close" class="close">×</button><p id="detailIntro"></p><div id="steps" class="steps"></div><div class="warning"><strong>સલામતી નોંધ:</strong> દવા/ડોઝ માત્ર સચોટ ઓળખ, સ્થાનિક કૃષિ નિષ્ણાતની સલાહ અને મંજૂર લેબલ મુજબ જ નક્કી કરો. અલગ-અલગ દવાઓ ભેળવીને છંટકાવ ન કરો.</div></div></section><aside class="safety"><strong>ખેડૂત માટે જરૂરી સૂચના:</strong> આ પાનું સામાન્ય માર્ગદર્શન માટે છે. જીવાતની સંખ્યા, પાકની અવસ્થા અને સ્થાનિક પરિસ્થિતિ પ્રમાણે નિર્ણય બદલાય છે. મોજાં, માસ્ક અને રક્ષણાત્મક કપડાં વગર કોઈપણ પાક-સુરક્ષા ઉત્પાદન વાપરશો નહીં.</aside></main>
