{id:'spider_mite',crop:'શાકભાજી · Vegetables',pest:'પાન કથીરી / Spider Mite',icon:'🕷️',cropIcon:'🍆',tone:'tomato',search:'spider mite pan kathiri vegetables',symptom:'પાંદડા પર ઝીણા સફેદ કે પીળા ટપકાં અને કરોળિયા જેવા જાળાં.',intro:'કથીરી ખૂબ જ સૂક્ષ્મ હોય છે અને ગરમ હવામાનમાં ઝડપથી વધે છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Tetranychus_urticae_with_silk_threads.jpg/500px-Tetranychus_urticae_with_silk_threads.jpg',steps:[['ભેજ જાળવો','વધુ પડતા સૂકા વાતાવરણમાં પાંદડા પર પાણીનો છંટકાવ કરો.'],['સલ્ફરનો ઉપયોગ','શરૂઆતમાં દ્રાવ્ય ગંધક (સલ્ફર) નો છંટકાવ ફાયદાકારક છે.'],['યોગ્ય દવા','માઇટીસાઇડ (કથીરીનાશક) નો નિષ્ણાતની સલાહથી ઉપયોગ કરો.']]},
{id:'jassid',crop:'કપાસ / ભીંડા · Cotton/Okra',pest:'તડતડીયા / Jassid',icon:'🦗',cropIcon:'🌿',tone:'cotton',search:'jassid leafhopper tadtadiya',symptom:'પાંદડાની કિનારીઓ પીળી પડીને નીચે તરફ વળી જાય છે (કપ આકાર).',intro:'તડતડીયા પાનમાંથી રસ ચૂસે છે જેથી છોડની વૃદ્ધિ અટકી જાય છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Two-lined_gum_treehopper03.jpg/500px-Two-lined_gum_treehopper03.jpg',steps:[['પ્રતિકારક જાતો','તડતડીયા સામે પ્રતિકારક શક્તિ ધરાવતા બીજ વાવો.'],['લીમડાનો અર્ક','5% લીંબોળીના અર્કનો સમયસર છંટકાવ કરો.'],['રાસાયણિક દવા','જો નુકસાન 5-10% થી વધે તો ભલામણ કરેલ રસચૂસક દવાનો છંટકાવ કરો.']]},
{id:'nematode',crop:'ટામેટાં / દાડમ · Tomato/Pomegranate',pest:'મૂળના કૃમિ / Nematode',icon:'🪱',cropIcon:'🍅',tone:'tomato',search:'nematode krumi root knot tomato',symptom:'છોડ પીળો પડે અને મૂળમાં નાની નાની ગાંઠો જોવા મળે.',intro:'કૃમિ નરી આંખે દેખાતા નથી, પરંતુ તે મૂળને પોષણ લેતા અટકાવે છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/A_juvenile_root-knot_nematode_%28Meloidogyne_incognita%29_penetrates_a_tomato_root_-_USDA-ARS.jpg/500px-A_juvenile_root-knot_nematode_%28Meloidogyne_incognita%29_penetrates_a_tomato_root_-_USDA-ARS.jpg',steps:[['પાક ફેરબદલી','દર વર્ષે એક જ પાક લેવાનું ટાળો અને જુવાર કે બાજરી વાવો.'],['ગલગોટાનું વાવેતર','ખેતરમાં આંતરપાક તરીકે ગલગોટા (Marigold) વાવો.'],['જૈવિક નિયંત્રણ','ટ્રાયકોડર્મા પ્લસ અથવા નિમેટોડનાશકનો જમીનમાં ઉપયોગ કરો.']]},
{id:'powdery_mildew',crop:'જીરું / કેરી · Cumin/Mango',pest:'ભૂકી છારો / Powdery Mildew',icon:'☁️',cropIcon:'🥭',tone:'maize',search:'powdery mildew bhuki chharo cumin',symptom:'પાંદડા અને ફળ પર સફેદ પાવડર જેવો છંટકાવ જોવા મળે.',intro:'આ ફૂગજન્ય રોગ વાદળછાયા અને ભેજવાળા હવામાનમાં ઝડપથી ફેલાય છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Powdery_mildew_on_oak_leaf.jpg/500px-Powdery_mildew_on_oak_leaf.jpg',steps:[['વેન્ટિલેશન','છોડ વચ્ચે યોગ્ય અંતર રાખો જેથી હવામાનની અવરજવર રહે.'],['સલ્ફર પાવડર','રોગની શરૂઆતમાં ગંધક (Sulfur) પાવડર છાંટો.'],['ફૂગનાશક','રોગ વધે તો હેક્ઝાકોનાઝોલ કે અન્ય મંજૂર દવાનો ઉપયોગ કરો.']]},
{id:'early_blight',crop:'બટાટા / ટામેટાં · Potato/Tomato',pest:'અર્લી બ્લાઈટ / Early Blight',icon:'🍂',cropIcon:'🥔',tone:'groundnut',search:'early blight alternaria tomato potato',symptom:'નીચેના પાંદડા પર કાળા અને ભૂખરા રંગના ગોળ ટપકાં (ટાર્ગેટ બોર્ડ).',intro:'આ રોગ પાંદડા ખેરવી નાખે છે અને ઉત્પાદનમાં મોટો ઘટાડો કરે છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Alternaria_solani_-_leaf_lesions.jpg/500px-Alternaria_solani_-_leaf_lesions.jpg',steps:[['પાક સ્વચ્છતા','રોગિષ્ટ પાંદડા અને છોડનો કચરો ખેતરમાંથી દૂર કરો.'],['પિયત વ્યવસ્થાપન','પાંદડા વધુ સમય ભીના ન રહે તે માટે ટપક સિંચાઈ વાપરો.'],['યોગ્ય ફૂગનાશક','મેન્કોઝેબ કે ક્લોરોથેલોનીલનો છંટકાવ રોગની શરૂઆતમાં જ કરો.']]},
{id:'brinjal_borer',crop:'રીંગણ · Brinjal',pest:'ડાળી/ફળ છેદક',icon:'🐛',cropIcon:'🍆',tone:'tomato',search:'brinjal shoot fruit borer ringan',symptom:'નવી ડાળીઓ સુકાઈને લટકી પડે અને ફળમાં કાણાં જોવા મળે.',intro:'આ ઇયળ રીંગણના પાકનો સૌથી મોટો દુશ્મન છે, જે ફળની અંદર રહીને નુકસાન કરે છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Leucinodes_orbonalis.jpg/500px-Leucinodes_orbonalis.jpg',steps:[['રોગિષ્ટ ભાગ કાપો','લટકતી ડાળીઓ અને કાણાંવાળા ફળ તોડીને દાટી દો.'],['ફેરોમોન ટ્રેપ','લ્યુસીનોડસ ફેરોમોન ટ્રેપ (હેક્ટરે 15-20) લગાવો.'],['દવાનો છંટકાવ','ઇયળ ફળમાં પેસે તે પહેલાં જ સ્પિનોસાદ જેવી દવાનો છંટકાવ કરો.']]},
{id:'fusarium_wilt',crop:'દિવેલા / કપાસ · Castor/Cotton',pest:'સૂકારો / Wilt',icon:'🥀',cropIcon:'🌿',tone:'cotton',search:'fusarium wilt sukaro castor',symptom:'છોડના પાંદડા પીળા પડીને એકબાજુથી નમી પડે અને છેવટે આખો છોડ સુકાય.',intro:'સૂકારો જમીનજન્ય ફૂગ છે જે છોડની જલવાહિની બ્લોક કરી દે છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Fusarium_wilt_symptom_tobacco.jpg/500px-Fusarium_wilt_symptom_tobacco.jpg',steps:[['રોગ મુક્ત બીજ','હંમેશા સૂકારા સામે પ્રતિકારક જાતો (દા.ત. GCH-7) નું વાવેતર કરો.'],['ટ્રાયકોડર્મા','વાવેતર વખતે અને પિયત સાથે ટ્રાયકોડર્મા ફૂગ જમીનમાં આપો.'],['પાક ફેરબદલી','એક જ ખેતરમાં સતત દિવેલા કે કપાસનું વાવેતર ન કરો.']]},
{id:'yellow_mosaic',crop:'મગ / સોયાબીન · Green gram/Soybean',pest:'પીળો પચરક / YMV',icon:'🦠',cropIcon:'🌱',tone:'maize',search:'yellow mosaic virus ymv pilo pachrak',symptom:'પાંદડા પર પીળા અને લીલા રંગના ધબ્બા જોવા મળે છે.',intro:'આ વાયરસ જન્ય રોગ છે જે સફેદમાખી દ્વારા એક છોડથી બીજા છોડમાં ફેલાય છે.',image:'https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Abutilon_pictum_serres_du_Luxembourg.jpg/500px-Abutilon_pictum_serres_du_Luxembourg.jpg',steps:[['સફેદમાખી નિયંત્રણ','રોગ ફેલાતો અટકાવવા સફેદમાખીનો નાશ કરવો સૌથી અગત્યનો છે.'],['રોગિષ્ટ છોડનો નાશ','શરૂઆતમાં દેખાતા પીળા છોડને ઉપાડીને બાળી નાખો.'],['પ્રતિકારક જાતો','વાયરસ સામે રોગ-પ્રતિકારક શક્તિ ધરાવતી પ્રમાણિત જાતો જ વાવો.']]}
];
const grid=document.getElementById('grid'),filter=document.getElementById('cropFilter'),search=document.getElementById('search'),detail=document.getElementById('detail');records.forEach(r=>filter.insertAdjacentHTML('beforeend',`<option value="${r.id}">${r.crop}</option>`));function render(){const q=search.value.toLowerCase().trim(),f=filter.value,result=records.filter(r=>(f==='all'||r.id===f)&&`${r.crop} ${r.pest} ${r.search}`.toLowerCase().includes(q));document.getElementById('count').textContent=`${result.length} માર્ગદર્શિકા`;grid.innerHTML=result.map(r=>`<article class="pest-card"><div class="card-visual ${r.tone}" style="background: url('${r.image}') center/cover; position: relative;"><span class="severity" style="background: rgba(255,255,255,0.95); color: #000;">વહેલી તપાસ</span></div><div class="card-body"><p class="crop-name">${r.crop}</p><h3>${r.pest}</h3><p class="symptoms"><strong>લક્ષણ:</strong> ${r.symptom}</p><button class="card-action" data-id="${r.id}">માર્ગદર્શન જુઓ <span>→</span></button></div></article>`).join('')||'<div class="empty" style="display:block">કોઈ પાક કે જીવાત મળી નથી. અન્ય શબ્દથી શોધો.</div>';grid.querySelectorAll('button[data-id]').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.id)))}function showDetail(id){const r=records.find(x=>x.id===id);detail.classList.add('visible');document.getElementById('detailIcon').textContent=r.icon;document.getElementById('detailCrop').textContent=r.crop;document.getElementById('detailName').textContent=r.pest;document.getElementById('detailIntro').textContent=r.intro;document.getElementById('detailVisual').style.background=`linear-gradient(150deg, rgba(36,88,58,0.85), rgba(36,88,58,0.65)), url('${r.image}') center/cover`;document.getElementById('steps').innerHTML=r.steps.map((s,i)=>`<div class="step"><div class="step-num">${i+1}</div><div><strong>${s[0]}</strong><span>${s[1]}</span></div></div>`).join('');detail.scrollIntoView({behavior:'smooth',block:'start'})}search.addEventListener('input',render);filter.addEventListener('change',render);document.getElementById('close').addEventListener('click',()=>detail.classList.remove('visible'));render();
</script></body></html>
